public class SA {
 public String typed(Object value) {
  if(value==null) return 'null';
  return String.valueOf(value)+'|Integer='+(value instanceof Integer)
   +'|Decimal='+(value instanceof Decimal)+'|Date='+(value instanceof Date)
   +'|String='+(value instanceof String)+'|AggregateResult='+(value instanceof AggregateResult);
 }
 public String signature(List<SObject> rows,List<String> keys) {
  List<String> values=new List<String>();
  for(SObject row:rows) {
   List<String> parts=new List<String>();
   for(String key:keys) parts.add(key+'='+String.valueOf(row.get(key)));
   values.add(String.join(parts,','));
  }
  values.sort(); return rows.size()+'|'+String.join(values,';');
 }
}

